def totient_sieve(limit: int) -> list[int]:
    """phi(n) for every n in 0..limit, computed with a sieve over the prime factors."""
    phi: list[int] = []
    for n in range(limit + 1):
        phi.append(n)
    for p in range(2, limit + 1):
        if phi[p] == p:
            for m in range(p, limit + 1, p):
                phi[m] = phi[m] // p * (p - 1)
    return phi

